/*===========================
  card-01 css
===========================*/
.single-card {
  box-shadow: var(--shadow-1);
  border-radius: 8px;
  overflow: hidden;
  margin-top: 30px;
  -webkit-transition: all 0.3s ease-out 0s;
  -moz-transition: all 0.3s ease-out 0s;
  -ms-transition: all 0.3s ease-out 0s;
  -o-transition: all 0.3s ease-out 0s;
  transition: all 0.3s ease-out 0s;
}
.single-card:hover {
  box-shadow: var(--shadow-4);
}
.single-card .card-image img {
  width: 100%;
  height: 100%;
}
.single-card .card-content {
  padding: 16px;
}
.single-card .card-content .card-title {
  margin-bottom: 0;
}
.single-card .card-content .card-title a {
  color: var(--black);
  -webkit-transition: all 0.3s ease-out 0s;
  -moz-transition: all 0.3s ease-out 0s;
  -ms-transition: all 0.3s ease-out 0s;
  -o-transition: all 0.3s ease-out 0s;
  transition: all 0.3s ease-out 0s;
}
.single-card .card-content .card-title a:hover {
  color: var(--primary);
}
.single-card .card-content .text {
  color: var(--dark-3);
  margin-top: 8px;
}

/*===== CARD STYLE 2 =====*/
.cards-style-3 { background: var(--light-2); padding: 65px 0; }
.cards-style-3 .item-card { background: var(--white); border: 1px solid var(--gray-4); border-radius: 6px; overflow: hidden; box-shadow: var(--shadow-2); transition: transform .25s ease, box-shadow .25s ease; height: 100%; }
.cards-style-3 .item-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-4); }
.cards-style-3 .card-thumb img { width: 100%; height: 210px; object-fit: cover; }
.cards-style-3 .card-body-content { padding: 24px; }
.cards-style-3 .tag-pill { display: inline-block; font-size: 12px; font-weight: 600; padding: 4px 12px; border-radius: 20px; background: var(--primary-light); color: var(--primary); }
.cards-style-3 h5 { color: var(--black); font-weight: 600; }
.cards-style-3 p { color: var(--dark-2); font-size: 15px; }
.cards-style-3 .read-link { color: var(--secondary); font-weight: 600; display: inline-flex; align-items: center; }

